    private void WireEvents(bool online) { FormClosing += (_, _) => _closing.Cancel(); _search.GotFocus += (_, _) => { if (!_searchHint) return; _searchHint = false; _search.Text = ""; _search.ForeColor = TextMain; }; _search.LostFocus += (_, _) => { if (!string.IsNullOrWhiteSpace(_search.Text)) return; _searchHint = true; _search.Text = "Buscar jogo..."; _search.ForeColor = TextMuted; }; _search.TextChanged += (_, _) => { if (!_searchHint) RefreshGameList(); }; _filter.SelectedIndexChanged += (_, _) => RefreshGameList(); if (online) Shown += async (_, _) => await InitializeAsync(); }
    private async Task InitializeAsync() { var bundled = Path.Combine(AppContext.BaseDirectory, "catalog.json"); _catalog = _storage.LoadCatalogCache() ?? _storage.Read<Catalog>(bundled) ?? new Catalog(); EnsureStates(); RefreshGameList(); try { _catalog = await _online.RefreshCatalogAsync(_closing.Token); Log($"Catálogo atualizado com {_catalog.Translations.Count} traduções."); } catch (Exception ex) { Log($"Catálogo online indisponível; usando cópia local. {ex.Message}"); } EnsureStates(); await ScanLibraryAsync(false); await CheckAppUpdateAsync(); }

    private async Task CheckAppUpdateAsync()
    {
        AppVersionManifest? update;
        try { update = await _online.CheckAppUpdateAsync(_closing.Token); }
        catch (OperationCanceledException) { return; }
        if (update is null || IsDisposed) return;

        var notes = string.IsNullOrWhiteSpace(update.Notes) ? "" : $"\r\n\r\nNovidades:\r\n{update.Notes}";
        var answer = MessageBox.Show(this, $"Uma nova versão da Central PT-BR está disponível.\r\n\r\nAtual: v{AppConstants.AppVersion}\r\nNova: v{update.Version}{notes}\r\n\r\nDeseja baixar e instalar agora?", "Atualização da Central PT-BR", MessageBoxButtons.YesNo, MessageBoxIcon.Information);
        if (answer != DialogResult.Yes) return;

        var executable = Environment.ProcessPath;
        if (string.IsNullOrWhiteSpace(executable) || !executable.EndsWith(".exe", StringComparison.OrdinalIgnoreCase) || Path.GetFileName(executable).Equals("dotnet.exe", StringComparison.OrdinalIgnoreCase))
        {
            OnlineServices.OpenUpdate(update);
            return;
        }

        try
        {
            _generalStatus.ForeColor = Yellow;
            var progress = new Progress<ProgressInfo>(info => { _generalStatus.Text = info.Percent.HasValue ? $"{info.Message} — {info.Percent}%" : info.Message; });
            var downloaded = await _online.DownloadUpdateAsync(update, _storage.Root, progress, _closing.Token);
            _generalStatus.Text = "Atualização validada. Reiniciando...";
            UpdateInstaller.Start(downloaded, executable, update.Sha256);
            _closing.Cancel();
            Application.Exit();
        }
        catch (OperationCanceledException) { }
        catch (Exception ex)
        {
            Log($"Falha ao atualizar a Central: {ex.Message}");
            _generalStatus.Text = "Falha ao atualizar a Central";
            _generalStatus.ForeColor = Red;
            MessageBox.Show(this, $"Não foi possível instalar a atualização.\r\n\r\n{ex.Message}", "Falha na atualização", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }
    private void EnsureStates() { foreach (var item in _catalog.Translations) { if (_storage.Installed.TryGetValue(item.Id, out var installed)) _states[item.Id] = CompareVersions(installed.Version, item.Version) < 0 ? LibraryState.UpdateAvailable : LibraryState.Installed; else if (_foundPaths.ContainsKey(item.Id)) _states[item.Id] = LibraryState.Available; else _states[item.Id] = LibraryState.NotFound; } }
    private async Task ScanLibraryAsync(bool announce)
    {
        SetBusy(true); _generalStatus.Text = "Escaneando bibliotecas Steam..."; _generalStatus.ForeColor = Yellow; if (announce) Log("Escaneamento geral iniciado."); try { await Task.Run(() => { foreach (var item in _catalog.Translations) { var path = SteamService.FindGame(item); if (path is not null) _foundPaths[item.Id] = path; } }); EnsureStates(); _storage.Config.LastCatalogCheck = DateTimeOffset.Now; _storage.SaveConfig(); _lastCheck.Text = $"Última verificação: {DateTime.Now:dd/MM/yyyy HH:mm}"; var updates = _states.Values.Any(x => x == LibraryState.UpdateAvailable); _generalStatus.Text = updates ? "Há atualizações disponíveis" : "Tudo atualizado!"; _generalStatus.ForeColor = updates ? Yellow : Green; RefreshGameList(); if (announce) Log("Escaneamento concluído."); } finally { SetBusy(false); }
    }
