em); }; row.Controls.Add(remove, 2, 0); var restore = ButtonOf("Restaurar original", false); restore.BackColor = Color.FromArgb(38, 75, 119); restore.FlatAppearance.BorderColor = Color.FromArgb(126, 178, 255); restore.Click += (_, _) => { if (string.IsNullOrWhiteSpace(item.SteamAppId)) { MessageBox.Show(this, "Este jogo não possui uma página Steam configurada.", "Steam", MessageBoxButtons.OK, MessageBoxIcon.Information); return; } RestoreSteam(item); }; row.Controls.Add(restore, 3, 0); return row;
