    private async Task InstallAsync(Translation item)
    {
        var path = _foundPaths.GetValueOrDefault(item.Id) ?? _storage.Config.GamePaths.GetValueOrDefault(item.Id); if (string.IsNullOrWhiteSpace(path) || !Directory.Exists(path)) { MessageBox.Show(this, "O jogo não foi localizado. Execute o escaneamento.", "Jogo não encontrado", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; } if (MessageBox.Show(this, $"Instalar a tradução de {item.Game}?", "Confirmar instalação", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return;
        try { SetBusy(true, "Instalando tradução"); await _translations.InstallAsync(item, path, new Progress<ProgressInfo>(UpdateOperation), _closing.Token); MessageBox.Show(this, "Tradução instalada com sucesso.", "Central PT-BR", MessageBoxButtons.OK, MessageBoxIcon.Information); } catch (Exception ex) { Log(ex.Message); MessageBox.Show(this, ex.Message, "Falha na instalação", MessageBoxButtons.OK, MessageBoxIcon.Error); } finally { SetBusy(false); EnsureStates(); RefreshGameList(); ShowDetails(item); }
    }
    private async Task RemoveAsync(Translation item)
    {
        if (MessageBox.Show(this, "Desinstalar a tradução e restaurar o backup original?", "Confirmar remoção", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return; try { SetBusy(true, "Removendo tradução"); var result = await _translations.RemoveAsync(item, new Progress<ProgressInfo>(UpdateOperation), _closing.Token); var note = result.RequiresSteamRestore ? " Alguns arquivos precisarão da verificação da Steam." : ""; MessageBox.Show(this, "Tradução removida com sucesso." + note, "Central PT-BR", MessageBoxButtons.OK, MessageBoxIcon.Information); } catch (Exception ex) { Log(ex.Message); MessageBox.Show(this, ex.Message, "Falha na remoção", MessageBoxButtons.OK, MessageBoxIcon.Error); } finally { SetBusy(false); EnsureStates(); RefreshGameList(); ShowDetails(item); }
    }
    private async Task VerifyAsync(Translation item)
    {
        if (!_storage.Installed.TryGetValue(item.Id, out var installed)) { MessageBox.Show(this, "Esta tradução ainda não está instalada.", "Verificação", MessageBoxButtons.OK, MessageBoxIcon.Information); return; } SetBusy(true, "Verificando arquivos"); var problems = 0; IProgress<ProgressInfo> progress = new Progress<ProgressInfo>(UpdateOperation); try { await Task.Run(async () => { for (var i = 0; i < installed.Files.Count; i++) { var file = installed.Files[i]; var path = Path.Combine(installed.GamePath, file.RelativePath); if (!File.Exists(path) || !string.Equals(await FileTools.Sha256Async(path), file.InstalledHash, StringComparison.OrdinalIgnoreCase)) problems++; progress.Report(new ProgressInfo($"Verificando arquivo {i + 1} de {installed.Files.Count}", (i + 1) * 100 / Math.Max(1, installed.Files.Count))); } }); } finally { SetBusy(false); } MessageBox.Show(this, problems == 0 ? "Todos os arquivos estão corretos." : $"Foram encontrados {problems} arquivo(s) alterado(s) ou ausente(s).", "Verificação concluída", MessageBoxButtons.OK, problems == 0 ? MessageBoxIcon.Information : MessageBoxIcon.Warning);
    }
    private void RestoreSteam(Translation item) { if (MessageBox.Show(this, "A Steam verificará e restaurará os arquivos originais. Continuar?", "Restaurar jogo original", MessageBoxButtons.YesNo, MessageBoxIcon.Warning) != DialogResult.Yes) return; try { SteamService.Validate(item.SteamAppId); } catch (Exception ex) { MessageBox.Show(this, ex.Message, "Steam", MessageBoxButtons.OK, MessageBoxIcon.Error); } }
    private void ShowSettings()
    {
        using var dialog = new Form { Text = "Configurações — Central PT-BR", StartPosition = FormStartPosition.CenterParent, Size = new Size(470, 330), BackColor = Panel, ForeColor = TextMain, Font = Font, FormBorderStyle = FormBorderStyle.FixedDialog, MaximizeBox = false, MinimizeBox = false }; var layout = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.TopDown, Padding = new Padding(24), BackColor = Panel, WrapContents = false }; layout.Controls.Add(LabelOf("CONFIGURAÇÕES", 14, FontStyle.Bold, TextMain, 390)); foreach (var text in new[] { "Escanear a Steam automaticamente ao iniciar", "Verificar catálogo ao iniciar", "Confirmar antes de instalar ou remover", "Mostrar log técnico quando houver erro" }) layout.Controls.Add(new CheckBox { Text = text, Checked = true, AutoSize = true, ForeColor = TextMain, Margin = new Padding(0, 12, 0, 0) }); var open = ButtonOf("Abrir pasta da Central PT-BR", false); open.Width = 390; open.Height = 42; open.Margin = new Padding(0, 18, 0, 0); open.Click += (_, _) => OpenFolder(_storage.Root); layout.Controls.Add(open); dialog.Controls.Add(layout); dialog.ShowDialog(this);
    }
    private void ToggleLog() { if (_logToggle.Tag is not TableLayoutPanel outer) return; var visible = outer.RowStyles[1].Height > 0; outer.RowStyles[1].SizeType = SizeType.Absolute; outer.RowStyles[1].Height = visible ? 0 : 160; _logToggle.Text = visible ? "Ver log" : "Ocultar log"; }
    private void UpdateSummary() { if (_summaryCatalog.IsDisposed) return; var installed = _states.Values.Count(x => x == LibraryState.Installed); var updates = _states.Values.Count(x => x == LibraryState.UpdateAvailable); var available = _states.Values.Count(x => x == LibraryState.Available); var missing = _states.Values.Count(x => x == LibraryState.NotFound); _summaryCatalog.Text = _catalog.Translations.Count.ToString(); _summaryInstalled.Text = installed.ToString(); _summaryUpdates.Text = updates.ToString(); _summaryAvailable.Text = available.ToString(); _summaryMissing.Text = missing.ToString(); _legendInstalled.Text = installed.ToString(); _legendUpdates.Text = updates.ToString(); _legendAvailable.Text = available.ToString(); _legendMissing.Text = missing.ToString(); }
    private LibraryState StateOf(Translation item) => _states.GetValueOrDefault(item.Id, LibraryState.NotFound);
    private static bool FilterMatches(LibraryState s, string f) => f switch { "Instalados" => s == LibraryState.Installed, "Disponíveis" => s == LibraryState.Available, "Atualizações" => s == LibraryState.UpdateAvailable, "Não encontrados" => s == LibraryState.NotFound, _ => true };
    private static string StateText(LibraryState s) => s switch { LibraryState.Installed => "Instalada", LibraryState.Available => "Disponível", LibraryState.UpdateAvailable => "Atualização disponível", _ => "Não encontrado" };
    private static Color StateColor(LibraryState s) => s switch { LibraryState.Installed => Green, LibraryState.Available => Color.FromArgb(58, 156, 255), LibraryState.UpdateAvailable => Yellow, _ => Gray };
    private static string CompatibilityText(Translation item) => string.IsNullOrWhiteSpace(item.SteamAppId) ? "Compatibilidade não verificada" : "Pronta para a versão Steam detectada";
    private static int CompareVersions(string a, string b) => Version.TryParse(a, out var av) && Version.TryParse(b, out var bv) ? av.CompareTo(bv) : string.Compare(a, b, StringComparison.OrdinalIgnoreCase);
    private static string FormatBytes(long b) => b >= 1024 * 1024 ? $"{b / 1024d / 1024d:0.0} MB" : $"{b / 1024d:0.0} KB";
    private static string IssueUrl(Translation item) { if (Uri.TryCreate(item.ReleaseUrl, UriKind.Absolute, out var uri) && uri.Host.Equals("github.com", StringComparison.OrdinalIgnoreCase)) { var p = uri.AbsolutePath.Trim('/').Split('/'); if (p.Length >= 2) return $"https://github.com/{p[0]}/{p[1]}/issues/new"; } return AppConstants.OfficialRepositoryUrl + "/issues/new"; }
    private void SetBusy(bool busy, string? title = null) { _busy = busy; UseWaitCursor = busy; if (_operationPanel is not null && _detailRoot is not null) { _operationPanel.Visible = busy; _detailRoot.RowStyles[3].Height = busy ? 78 : 0; _detailRoot.PerformLayout(); } if (busy) { if (_operationTitle is not null && !string.IsNullOrWhiteSpace(title)) _operationTitle.Text = title; if (_operationDetail is not null) _operationDetail.Text = "Preparando..."; if (_operationPercent is not null) _operationPercent.Text = "0%"; if (_operationBar is not null) { _operationBar.Style = ProgressBarStyle.Marquee; _operationBar.MarqueeAnimationSpeed = 25; } } }
    private void UpdateOperation(ProgressInfo info) { if (InvokeRequired) { BeginInvoke(() => UpdateOperation(info)); return; } if (_operationDetail is not null) _operationDetail.Text = info.Message; _generalStatus.Text = info.Message; if (!info.Percent.HasValue) { if (_operationBar is not null) { _operationBar.Style = ProgressBarStyle.Marquee; _operationBar.MarqueeAnimationSpeed = 25; } if (_operationPercent is not null) _operationPercent.Text = "..."; return; } var percent = Math.Clamp(info.Percent.Value, 0, 100); if (_operationBar is not null) { _operationBar.Style = ProgressBarStyle.Continuous; _operationBar.Value = percent; } if (_operationPercent is not null) _operationPercent.Text = $"{percent}%"; }
    private void Log(string message) { if (InvokeRequired) { BeginInvoke(() => Log(message)); return; } _log.AppendText($"[{DateTime.Now:HH:mm:ss}] {message}\r\n"); _log.ScrollToCaret(); }
    private static void OpenUrl(string? url) { if (!string.IsNullOrWhiteSpace(url)) Process.Start(new ProcessStartInfo(url) { UseShellExecute = true }); }
    private static void OpenFolder(string? path) { if (!string.IsNullOrWhiteSpace(path) && Directory.Exists(path)) Process.Start(new ProcessStartInfo("explorer.exe", $"\"{path}\"") { UseShellExecute = true }); }
    private static Panel Card() { var p = new Panel { Dock = DockStyle.Fill, BackColor = Panel }; p.Paint += (_, e) => { using var pen = new Pen(Border); e.Graphics.DrawRectangle(pen, 0, 0, Math.Max(0, p.ClientSize.Width - 2), Math.Max(0, p.ClientSize.Height - 2)); }; return p; }
    private static Label LabelOf(string text, float size, FontStyle style, Color color, int width = 0) => new() { Text = text, Dock = width == 0 ? DockStyle.Fill : DockStyle.None, Width = width, Height = 26, ForeColor = color, BackColor = Color.Transparent, Font = new Font("Segoe UI", size, style), TextAlign = ContentAlignment.MiddleLeft, AutoEllipsis = true };
    private static Button ButtonOf(string text, bool primary) { var b = new Button { Text = text, Dock = DockStyle.Fill, Margin = new Padding(4), FlatStyle = FlatStyle.Flat, BackColor = primary ? Blue : Panel2, ForeColor = TextMain, Font = new Font("Segoe UI", 10), Cursor = Cursors.Hand, UseVisualStyleBackColor = false, TextAlign = ContentAlignment.MiddleCenter }; b.FlatAppearance.BorderSize = 1; b.FlatAppearance.BorderColor = primary ? Blue : Border; return b; }
    private static void StyleInput(Control input) { var inputColor = Color.FromArgb(30, 67, 105); input.BackColor = inputColor; input.ForeColor = TextMain; input.Font = new Font("Segoe UI", 10); if (input is TextBox textBox) { textBox.BorderStyle = BorderStyle.FixedSingle; textBox.Padding = new Padding(8, 3, 8, 3); } if (input is ComboBox comboBox) { comboBox.FlatStyle = FlatStyle.Flat; comboBox.DrawMode = DrawMode.OwnerDrawFixed; comboBox.DrawItem += (_, e) => { if (e.Index < 0) return; using var background = new SolidBrush(inputColor); e.Graphics.FillRectangle(background, e.Bounds); using var brush = new SolidBrush(TextMain); e.Graphics.DrawString(comboBox.Items[e.Index]?.ToString() ?? "", comboBox.Font, brush, e.Bounds.Left + 6, e.Bounds.Top + 2); }; } }
    private static LinkLabel LinkOf(string text, string url) { var l = new LinkLabel { Text = text, AutoSize = true, LinkColor = Color.FromArgb(58, 156, 255), ActiveLinkColor = Color.White, BackColor = Panel, Margin = new Padding(0, 9, 28, 0) }; l.LinkClicked += (_, _) => OpenUrl(url); return l; }
    private static void AddInfo(TableLayoutPanel table, int row, string name, string value) { table.RowStyles.Add(new RowStyle(SizeType.Percent, 16)); table.Controls.Add(LabelOf(name, 9, FontStyle.Regular, TextMuted), 0, row); var label = LabelOf(value, 9, FontStyle.Regular, value.Contains("OK") ? Green : TextMain); label.TextAlign = ContentAlignment.MiddleRight; table.Controls.Add(label, 1, row); }
}
